mapper.select:
SELECT ID, TEMPLATE_TYPE, TEMPLATE_CODE, BUCKET_NAME, OBJECT_NAME, STATUS FROM ( SELECT T.ID, T.TEMPLATE_TYPE, T.TEMPLATE_CODE, T.BUCKET_NAME, T.OBJECT_NAME, T.STATUS, ROW_NUMBER() OVER ( ORDER BY
${orderBy} T.ID DESC
) RN FROM E_PRINT_TEMPLATE T WHERE 1 = 1
AND T.TEMPLATE_TYPE = #{templateType}
AND LOWER(T.TEMPLATE_CODE) LIKE '%' || LOWER(#{templateCode}) || '%'
AND T.STATUS = #{status}
) WHERE RN > #{rowStart} AND RN <= #{rowEnd} ORDER BY RN

SELECT COUNT(1)
FROM E_PRINT_TEMPLATE T
WHERE 1 = 1

    AND T.TEMPLATE_TYPE = #{templateType}


    AND LOWER(T.TEMPLATE_CODE) LIKE '%' || LOWER(#{templateCode}) || '%'


    AND T.STATUS = #{status}

mapper.update:
UPDATE E_PRINT_TEMPLATE
SET STATUS = 0
WHERE ID = #{id}

UPDATE E_PRINT_TEMPLATE
SET STATUS = 1
WHERE ID = #{id}

UPDATE E_PRINT_TEMPLATE
SET STATUS = #{status}
WHERE ID IN

    #{id}

mapper.delete:
